"""ms — virtues_c."""

T = {
"virtues_051": ("Apakah nasihat Luqman kepada anaknya tentang suara?", ["Merendahkannya: seburuk-buruk suara ialah suara keldai", "Bercakap sekuat-kuatnya", "Tidak bercakap langsung", "Menyanyi sambil berjalan"], "«Dan sederhanakanlah langkahmu serta rendahkanlah suaramu: sesungguhnya seburuk-buruk suara ialah suara keldai.»"),
"virtues_052": ("Tiga nasihat manakah yang diberi Luqman kepada anaknya sebelum bercakap tentang kesabaran?", ["Dirikan solat, suruh yang makruf, cegah yang mungkar", "Mengembara, berniaga, menulis", "Makan sedikit, tidur sedikit, bercakap sedikit", "Membina, menanam, menuai"], "«Wahai anakku, dirikanlah solat, suruhlah berbuat makruf, cegahlah daripada yang mungkar, dan bersabarlah atas apa yang menimpamu.»"),
"virtues_053": ("Tiga sifat manakah yang diberikan al-Quran kepada orang bertakwa, dalam Surah Ali 'Imran?", ["Berinfak ketika senang dan susah, menahan marah, memaafkan manusia", "Puasa, solat malam, diam", "Membina, menanam, memberi", "Mengembara, belajar, mengajar"], "«Iaitu mereka yang berinfak ketika senang dan susah, yang menahan marah dan memaafkan manusia — dan Allah mengasihi orang yang berbuat baik.»"),
"virtues_054": ("Apakah yang dianggap al-Quran lebih baik daripada sedekah yang diiringi sakitan hati?", ["Perkataan yang baik dan kemaafan", "Pemberian yang lebih besar", "Diam sepenuhnya", "Satu sumpah"], "«Perkataan yang baik dan kemaafan itu lebih baik daripada sedekah yang diiringi sakitan hati.»"),
"virtues_055": ("Apakah yang dikatakan al-Quran tentang sedekah yang diberi secara rahsia?", ["Ia lebih baik bagi pemberinya", "Ia tidak dikira", "Ia mesti diumumkan", "Ia dilarang"], "«Jika kamu menzahirkan sedekah kamu, itu baik; tetapi jika kamu menyembunyikannya dan memberikannya kepada orang fakir, itu lebih baik bagi kamu.»"),
"virtues_056": ("Apakah yang dilarang al-Quran untuk diberikan sebagai sedekah?", ["Apa yang kamu sendiri tidak akan menerimanya melainkan dengan memejamkan mata", "Yang baharu", "Yang kamu sayangi", "Yang datang daripada pusaka"], "«Dan janganlah kamu memilih yang buruk untuk disedekahkan, sedangkan kamu sendiri tidak mahu mengambilnya melainkan dengan memejamkan mata.»"),
"virtues_057": ("Bilakah kebaikan yang sebenar dicapai, menurut Surah Ali 'Imran?", ["Dengan menginfakkan apa yang kamu sayangi", "Dengan menginfakkan lebihan", "Dengan menginfakkan di khalayak", "Dengan menyimpan semuanya"], "«Kamu sekali-kali tidak akan mencapai kebaikan sehingga kamu menginfakkan sebahagian daripada apa yang kamu sayangi.»"),
"virtues_058": ("Gambaran apakah yang digunakan al-Quran bagi keseimbangan dalam berbelanja?", ["Jangan jadikan tanganmu terbelenggu ke leher, dan jangan pula membukanya selebar-lebarnya", "Menutup pintu", "Berjalan perlahan", "Mengira dua kali"], "«Dan janganlah engkau jadikan tanganmu terbelenggu ke lehermu, dan jangan pula engkau membukanya selebar-lebarnya, nanti engkau menjadi tercela lagi menyesal.»"),
"virtues_059": ("Bagaimanakah al-Quran menggambarkan perbelanjaan «hamba-hamba Yang Maha Pemurah»?", ["Tidak boros dan tidak kedekut, tetapi pertengahan antara keduanya", "Sentiasa memberi tanpa batas", "Sentiasa menyimpan", "Tidak pernah memberi"], "«Dan mereka yang apabila berbelanja tidak berlebih-lebihan dan tidak pula kedekut, tetapi pertengahan antara keduanya.»"),
"virtues_060": ("Apakah yang diperintahkan al-Quran sebelum memasuki rumah yang bukan milik sendiri?", ["Meminta izin dan memberi salam kepada penghuninya", "Mengetuk tiga kali lalu masuk", "Terus masuk", "Memanggil dari jauh"], "«Janganlah kamu memasuki rumah yang bukan rumah kamu sehingga kamu meminta izin dan memberi salam kepada penghuninya.»"),
"virtues_061": ("Apakah yang perlu dilakukan jika diminta kembali, menurut Surah an-Nur?", ["Kembali: itu lebih suci bagi kamu", "Berkeras", "Menunggu di pintu", "Tetap masuk"], "«Dan jika dikatakan kepada kamu: “Kembalilah”, maka kembalilah; itu lebih suci bagi kamu.»"),
"virtues_062": ("Apakah yang diperintahkan al-Quran apabila orang yang tidak dipercayai membawa berita?", ["Menyelidikinya, agar tiada orang dirugikan kerana kejahilan", "Menyebarkannya serta-merta", "Menulisnya", "Sentiasa mengabaikannya"], "«Jika datang kepada kamu orang fasik membawa berita, maka selidikilah, agar kamu tidak menimpakan musibah kepada suatu kaum kerana kejahilan lalu kamu menyesal.»"),
"virtues_063": ("Perbuatan apakah, di samping mengumpat, yang dilarang Surah al-Hujurat?", ["Mengintip dan bersangka buruk berlebihan", "Mengembara seorang diri", "Bercakap perlahan", "Menulis surat"], "«Wahai orang yang beriman, jauhilah kebanyakan prasangka; sesungguhnya sebahagian prasangka itu dosa. Dan janganlah kamu mengintip dan mengumpat sesama sendiri.»"),
"virtues_064": ("Apakah yang diperintahkan al-Quran apabila dua kumpulan orang beriman berperang?", ["Mendamaikan mereka dengan adil", "Memihak kepada satu pihak", "Mengabaikan mereka", "Memisahkan mereka dengan kekerasan semata-mata"], "«Dan jika dua golongan orang beriman berperang, damaikanlah antara keduanya… dan berlaku adillah. Sesungguhnya Allah mengasihi orang yang berlaku adil.»"),
"virtues_065": ("Apakah yang dilarang al-Quran secara tegas, walaupun terhadap kaum yang dibenci?", ["Membiarkan kebencian memesongkan daripada keadilan", "Perniagaan", "Percakapan", "Berjiran"], "«Dan janganlah kebencian kamu terhadap suatu kaum mendorong kamu berlaku tidak adil. Berlaku adillah; itu lebih hampir kepada takwa.»"),
"virtues_066": ("Terhadap siapakah al-Quran menuntut kesaksian yang adil, jika perlu?", ["Terhadap diri sendiri, ibu bapa dan kaum kerabat", "Terhadap orang asing sahaja", "Terhadap orang kaya sahaja", "Terhadap orang miskin sahaja"], "«Jadilah kamu penegak keadilan, menjadi saksi kerana Allah, walaupun terhadap diri kamu sendiri, ibu bapa dan kaum kerabat kamu.»"),
"virtues_067": ("Apakah yang diperintahkan al-Quran untuk dikembalikan kepada yang berhak?", ["Amanah", "Surat", "Hasil tuaian", "Cerita"], "«Sesungguhnya Allah memerintahkan kamu menunaikan amanah kepada yang berhak menerimanya, dan apabila kamu menghukum antara manusia, hendaklah kamu menghukum dengan adil.»"),
"virtues_068": ("Golongan manakah yang disenaraikan ayat 4:36 untuk dilayan dengan baik, selepas ibu bapa?", ["Kaum kerabat, anak yatim, orang miskin, jiran dekat dan jauh, rakan, ibnu sabil dan hamba", "Raja dan ketua", "Peniaga", "Ulama sahaja"], "«Sembahlah Allah dan janganlah kamu mempersekutukan-Nya, dan berbuat baiklah kepada ibu bapa, kaum kerabat, anak yatim, orang miskin, jiran dekat, jiran jauh, rakan sekerja, ibnu sabil, dan hamba sahaya kamu.»"),
"virtues_069": ("Apakah yang diperintahkan al-Quran terhadap orang berhutang yang dalam kesempitan?", ["Memberi tempoh sehingga dia berkelapangan", "Mengejarnya", "Menggandakan hutang", "Mengusirnya"], "«Dan jika dia dalam kesukaran, berilah tempoh sehingga dia berkelapangan. Dan jika kamu menyedekahkannya, itu lebih baik bagi kamu.»"),
"virtues_070": ("Apakah yang diperintahkan ayat terpanjang dalam al-Quran bagi hutang bertempoh?", ["Agar ia ditulis", "Agar ia dirahsiakan", "Agar ia dilupakan", "Agar ia disampaikan secara lisan"], "«Wahai orang yang beriman, apabila kamu berhutang untuk tempoh yang ditentukan, hendaklah kamu menulisnya.»"),
"virtues_071": ("Apakah yang dilarang al-Quran berkaitan harta orang lain?", ["Memakannya secara batil, atau menggunakannya untuk merasuah hakim", "Menghitungnya", "Menjualnya", "Menyimpannya"], "«Dan janganlah kamu memakan harta sesama kamu secara batil, dan jangan kamu bawa urusan harta itu kepada hakim supaya kamu dapat memakan sebahagian harta orang lain dengan dosa.»"),
"virtues_072": ("Apakah yang diperintahkan al-Quran berkaitan harta anak yatim?", ["Menyerahkannya kepada mereka, tanpa menukar yang baik dengan yang buruk", "Membahagikannya", "Menjualnya", "Menyimpannya seumur hidup"], "«Dan berikanlah kepada anak yatim harta mereka, dan janganlah kamu menukar yang baik dengan yang buruk, dan janganlah kamu makan harta mereka bersama harta kamu.»"),
"virtues_073": ("Bagaimanakah al-Quran memerintahkan menyukat dan menimbang?", ["Sempurnakan sukatan dan timbanglah dengan neraca yang lurus", "Membulatkan untuk faedah sendiri", "Menimbang dengan agakan", "Menyukat dua kali"], "«Dan sempurnakanlah sukatan apabila kamu menyukat, dan timbanglah dengan neraca yang lurus. Itulah yang lebih baik dan lebih elok kesudahannya.»"),
"virtues_074": ("Apakah yang dilarang al-Quran untuk diikuti, tanpa pengetahuan?", ["Apa yang tiada padanya pengetahuan: pendengaran, penglihatan dan hati akan dipertanggungjawabkan", "Jalan yang terdekat", "Kafilah", "Diam"], "«Dan janganlah engkau mengikuti apa yang engkau tiada pengetahuan mengenainya. Sesungguhnya pendengaran, penglihatan dan hati, semuanya itu akan dipertanggungjawabkan.»"),
"virtues_075": ("Gambaran apakah yang diberikan al-Quran tentang kesombongan dalam berjalan?", ["Engkau tidak akan dapat menembusi bumi, dan tidak pula setinggi gunung", "Engkau berjalan lebih pantas", "Engkau kurang letih", "Engkau mendapat hormat"], "«Dan janganlah engkau berjalan di bumi dengan sombong. Sesungguhnya engkau tidak akan dapat menembusi bumi, dan tidak pula akan setinggi gunung.»"),
"virtues_076": ("Sifat percakapan apakah yang diperintahkan al-Quran, dengan janji amalan akan diperbaiki?", ["Perkataan yang tepat dan benar (qaulan sadida)", "Perkataan yang ringkas", "Perkataan yang berilmu", "Perkataan yang bertulis"], "«Wahai orang yang beriman, bertakwalah kepada Allah dan ucapkanlah perkataan yang tepat. Nescaya Dia memperbaiki amalan kamu dan mengampunkan dosa kamu.»"),
"virtues_077": ("Percakapan jenis apakah yang diperintahkan walaupun di hadapan seorang zalim, dalam al-Quran?", ["Percakapan yang lemah lembut", "Percakapan yang mengancam", "Percakapan yang menyindir", "Diam"], "«Dan berbicaralah kepadanya dengan kata-kata yang lemah lembut, mudah-mudahan dia ingat atau takut.»"),
"virtues_078": ("Tentang siapakah al-Quran berkata perkataannya yang terbaik?", ["Orang yang menyeru kepada Allah, beramal soleh dan berkata: aku termasuk orang Islam", "Penyair", "Ahli pidato", "Hakim"], "«Dan siapakah yang lebih baik perkataannya daripada orang yang menyeru kepada Allah, beramal soleh dan berkata: sesungguhnya aku termasuk orang yang berserah diri?»"),
"virtues_079": ("Daripada apakah orang beriman yang berjaya berpaling, menurut al-Mu'minun?", ["Daripada perkara sia-sia (al-laghw)", "Daripada kerja", "Daripada perjalanan", "Daripada makanan"], "«Dan mereka yang berpaling daripada perkara yang sia-sia.»"),
"virtues_080": ("Dua amanah manakah yang dipelihara orang beriman yang berjaya, menurut al-Mu'minun?", ["Amanah dan janji mereka", "Puasa dan solat malam", "Perjalanan dan perniagaan", "Penulisan dan pembacaan"], "«Dan mereka yang memelihara amanah dan janji mereka.»"),
"virtues_081": ("Apakah yang dikatakan al-Quran tentang orang yang memaafkan dan mendamaikan, walaupun mampu membalas?", ["Ganjarannya di sisi Allah", "Dia kehilangan haknya", "Dia dicela", "Dia mesti berdiam"], "«Balasan sesuatu kejahatan ialah kejahatan yang setimpal, tetapi sesiapa yang memaafkan dan mendamaikan, maka ganjarannya di sisi Allah.»"),
"virtues_082": ("Apakah hujah al-Quran untuk memaafkan orang yang menzalimimu?", ["«Tidakkah kamu suka Allah mengampunkan kamu?»", "«Kamu akan dibayar dengan wang»", "«Ia akan menjadikan kamu berkuasa»", "«Ia akan mengelakkan kamu daripada perbicaraan»"], "«Hendaklah mereka memaafkan dan berlapang dada. Tidakkah kamu suka Allah mengampunkan kamu? Dan Allah Maha Pengampun lagi Maha Penyayang.»"),
"virtues_083": ("Tiga arahan manakah yang dihimpunkan ayat 7:199?", ["Ambil apa yang mudah diberi, suruh yang makruf, berpaling daripada orang jahil", "Berperang, lari, berdiam", "Makan, minum, tidur", "Mengira, menulis, membaca"], "«Ambillah apa yang mudah diberi, suruhlah yang makruf, dan berpalinglah daripada orang jahil.»"),
"virtues_084": ("Sikap apakah yang disarankan al-Quran ketika menghadapi kata-kata menyakitkan dan ujian?", ["Sabar dan takwa: itulah perkara yang memerlukan keazaman", "Membalas serta-merta", "Mengasingkan diri selamanya", "Diam dengan sinis"], "«Dan kamu pasti akan mendengar banyak kata-kata menyakitkan daripada orang yang diberi Kitab sebelum kamu. Tetapi jika kamu bersabar dan bertakwa, itulah perkara yang memerlukan keazaman.»"),
"virtues_085": ("Bagaimanakah al-Quran menggambarkan kesabaran dan kemaafan?", ["Ia antara perkara yang memerlukan keazaman", "Ia kelemahan", "Ia pilihan sahaja", "Ia untuk ulama sahaja"], "«Dan sesiapa yang bersabar dan memaafkan, sesungguhnya itu antara perkara yang memerlukan keazaman.»"),
"virtues_086": ("Bagi siapakah al-Quran mengatakan solat itu tidak berat?", ["Bagi orang yang khusyuk (al-khasyi'in)", "Bagi orang kaya", "Bagi ulama", "Bagi musafir"], "«Dan mintalah pertolongan dengan sabar dan solat; sesungguhnya ia berat, kecuali bagi orang yang khusyuk.»"),
"virtues_087": ("Apakah yang diingatkan al-Quran tentang apa yang dibenci atau disukai?", ["Boleh jadi kamu membenci sesuatu yang baik bagimu, dan menyukai sesuatu yang buruk bagimu", "Apa yang kamu sukai sentiasa baik", "Apa yang kamu benci sentiasa buruk", "Kamu sentiasa tahu apa yang baik"], "«Boleh jadi kamu membenci sesuatu sedangkan ia baik bagi kamu, dan boleh jadi kamu menyukai sesuatu sedangkan ia buruk bagi kamu. Allah mengetahui sedang kamu tidak mengetahui.»"),
"virtues_088": ("Apakah yang dijanjikan al-Quran kepada orang yang bertakwa, tentang jalan keluar dan rezeki?", ["Jalan keluar, dan rezeki dari arah yang tidak disangka", "Kekayaan segera", "Perjalanan jauh", "Jawatan awam"], "«Dan sesiapa yang bertakwa kepada Allah, nescaya Dia mengadakan baginya jalan keluar, dan memberinya rezeki dari arah yang tidak disangkanya.»"),
"virtues_089": ("Kesyukuran apakah yang diperintahkan al-Quran seiring dengan kesyukuran kepada Allah?", ["Kesyukuran kepada ibu bapa", "Kepada tuannya", "Kepada jirannya", "Kepada rajanya"], "«Bersyukurlah kepada-Ku dan kepada kedua ibu bapamu; kepada-Kulah tempat kembali.»"),
"virtues_090": ("Apakah batas yang ditetapkan al-Quran bagi ketaatan kepada ibu bapa?", ["Tidak mentaati mereka jika menyuruh mempersekutukan Allah", "Tidak mentaati mereka langsung", "Mentaati mereka dalam segala hal", "Mentaati mereka hanya ketika bermusafir"], "«Tetapi jika keduanya memaksamu mempersekutukan-Ku dengan sesuatu yang engkau tiada pengetahuan mengenainya, janganlah engkau mentaati keduanya; dan pergaulilah keduanya di dunia dengan baik.»"),
"virtues_091": ("Doa apakah yang diajarkan al-Quran bagi ibu bapa dan keturunan?", ["Bersyukur atas nikmat, beramal soleh, dan agar keturunannya diperbaiki", "Memohon kekayaan", "Memohon perjalanan jauh", "Memohon jawatan"], "«Wahai Tuhanku, berilah aku ilham untuk mensyukuri nikmat-Mu yang Engkau kurniakan kepadaku dan kepada kedua ibu bapaku, dan agar aku beramal soleh; dan perbaikilah keturunanku.»"),
"virtues_092": ("Apakah yang dipohon «hamba-hamba Yang Maha Pemurah» tentang keluarga mereka?", ["Agar menjadi penyejuk mata, dan agar mereka menjadi teladan bagi orang bertakwa", "Agar mereka kaya", "Agar mereka ramai", "Agar mereka mengembara"], "«Wahai Tuhan kami, kurniakanlah kepada kami penyejuk mata daripada isteri dan keturunan kami, dan jadikanlah kami teladan bagi orang yang bertakwa.»"),
"virtues_093": ("Bagaimanakah «hamba-hamba Yang Maha Pemurah» bertindak ketika berhadapan dengan perkara sia-sia?", ["Mereka berlalu dengan menjaga kehormatan diri", "Mereka berhenti mendengar", "Mereka menjawab dengan kasar", "Mereka menulisnya"], "«Dan mereka yang tidak memberi kesaksian palsu, dan apabila mereka melalui perkara yang sia-sia, mereka berlalu dengan menjaga kehormatan diri.»"),
"virtues_094": ("Apakah yang diperintahkan al-Quran dalam majlis apabila diminta memberi ruang?", ["Berilah ruang: Allah akan meluaskan untuk kamu", "Tetap berhimpit", "Beredar", "Berdiam"], "«Wahai orang yang beriman, apabila dikatakan kepada kamu: “Berilah ruang dalam majlis”, maka berilah ruang; nescaya Allah meluaskan untuk kamu.»"),
"virtues_095": ("Bersama siapakah al-Quran memerintahkan supaya berada, dalam Surah at-Taubah?", ["Bersama orang yang benar", "Bersama orang yang berkuasa", "Bersama orang kaya", "Bersama musafir"], "«Wahai orang yang beriman, bertakwalah kepada Allah dan hendaklah kamu bersama orang yang benar.»"),
"virtues_096": ("Bersama siapakah al-Quran memerintahkan Nabi ﷺ bersabar menemani, dalam al-Kahfi?", ["Mereka yang menyeru Tuhan mereka pagi dan petang, mengharapkan wajah-Nya", "Ketua-ketua kabilah", "Peniaga-peniaga kaya", "Para penyair"], "«Dan bersabarlah bersama orang yang menyeru Tuhan mereka pada waktu pagi dan petang, mengharapkan wajah-Nya; dan janganlah engkau palingkan matamu daripada mereka.»"),
"virtues_097": ("Atas perkara apakah al-Quran memerintahkan tolong-menolong, dan atas apakah ia melarangnya?", ["Tolong-menolonglah dalam kebaikan dan takwa, bukan dalam dosa dan permusuhan", "Tolong-menolong dalam segala hal", "Jangan menolong sesiapa", "Tolong-menolong dalam keluarga sahaja"], "«Dan tolong-menolonglah kamu dalam kebaikan dan takwa, dan janganlah tolong-menolong dalam dosa dan permusuhan.»"),
"virtues_098": ("Apakah yang diperintahkan al-Quran tentang janji yang dibuat dan sumpah yang dikukuhkan?", ["Menyempurnakan janji dan tidak melanggar sumpah setelah dikukuhkan", "Merundingnya semula", "Melupakannya", "Menyembunyikannya"], "«Dan sempurnakanlah janji Allah apabila kamu berjanji, dan janganlah kamu melanggar sumpah setelah dikukuhkan.»"),
"virtues_099": ("Menurut hadis riwayat al-Bukhari, bilakah sempurna iman seseorang?", ["Apabila dia mencintai untuk saudaranya apa yang dicintainya untuk dirinya sendiri", "Apabila dia berpuasa sepanjang tahun", "Apabila dia menyedekahkan seluruh hartanya", "Apabila dia mengembara ke Makkah"], "«Tidak sempurna iman seseorang antara kamu sehingga dia mencintai untuk saudaranya apa yang dicintainya untuk dirinya sendiri.»"),
"virtues_100": ("Dalam keadaan apakah al-Quran melihat kebaikan dalam perbualan rahsia?", ["Menyeru kepada sedekah, kebaikan, atau perdamaian antara manusia", "Membincangkan perniagaan", "Merancang perjalanan", "Menyampaikan berita"], "«Tiada kebaikan pada kebanyakan bisikan mereka, kecuali bisikan orang yang menyuruh bersedekah, atau berbuat makruf, atau mendamaikan antara manusia.»"),
}
